<template>
  <main class="batter-period-page">
    <ComparisonPageHeader eyebrow="Batter comparison" title="Batter Period Comparison" description="The pitcher comparison workflow, adapted for hitter production, contact quality, decisions, bat tracking, and timing." back-to="/batters/comparison" back-label="Batter comparison" />
    <ComparisonPeriodSetup v-model:left-year="leftYear" v-model:right-year="rightYear" v-model:left-start="leftStart" v-model:left-end="leftEnd" v-model:right-start="rightStart" v-model:right-end="rightEnd" :years="yearOptions" :can-apply="canApply" :pending="pending" @apply="loadComparison">
      <template #directory>
        <label>Directory year<select v-model.number="directoryYear"><option v-for="year in yearOptions" :key="year" :value="year">{{ year }}</option></select></label>
        <label>Team<select v-model="team"><option value="All">All teams</option><option v-for="value in teamOptions" :key="value" :value="value">{{ value }}</option></select></label>
        <label>Batter<select v-model.number="batterId"><option :value="null">Select batter</option><option v-for="batter in batterOptions" :key="batter.value" :value="batter.value">{{ batter.label }}</option></select></label>
      </template>
      <template #between><ComparisonTransferPanel v-if="teamStints.length > 1" v-model:left-index="leftStintIndex" v-model:right-index="rightStintIndex" :stints="teamStints" :pending="pending" @compare="applyStintComparison" /></template>
    </ComparisonPeriodSetup>
    <ComparisonStatus :pending="pending" :error="errorMessage" label="Recalculating both batter periods…" />
    <p v-if="canApply && !comparison && !pending" class="apply-hint">Select a batter and date windows, then apply to load the period comparison.</p>
    <template v-if="comparison && selectedBatter">
      <ComparisonCardsGrid>
        <template #left><PercentileMirrorCard side="left" :player="periodPlayer('left')" :metrics="comparison.percentile_cards.left" /></template>
        <template #right><PercentileMirrorCard side="right" :player="periodPlayer('right')" :metrics="comparison.percentile_cards.right" /></template>
      </ComparisonCardsGrid>
      <ComparisonMetricDetails table-title="Period Metric Comparison" :table="metricComparisonTable" :max-rows="40" summary-title="Period Snapshot" :summary-subtitle="`${comparison.periods.left.pitches.toLocaleString()} pitches vs ${comparison.periods.right.pitches.toLocaleString()} pitches`" left-title="Period A Edge" right-title="Period B Edge" :left-rows="leftAdvantages" :right-rows="rightAdvantages" value-mode="display" />
      <ComparisonPeriodWorkspace v-model:open="filterRailOpen" filter-title="Batter Filters">
        <BatterPeriodHeatmaps :left-points="comparison.heatmaps.left" :right-points="comparison.heatmaps.right" :bat-speed-domain="comparison.bat_speed_domain" />
        <ComparisonPeriodDiscipline :left="comparison.discipline.left" :right="comparison.discipline.right" :group-filter="periodPanelGroup" />
        <template #filters>
          <label>Stand<select v-model="batterSide"><option v-for="value in filterOptions.batter_side" :key="value" :value="value">{{ value }}</option></select></label><label>Pitcher hand<select v-model="pitcherHand"><option v-for="value in filterOptions.pitcher_hand" :key="value" :value="value">{{ value }}</option></select></label><label>Pitch family<select v-model="pitchFamily"><option v-for="value in filterOptions.pitch_family" :key="value" :value="value">{{ value }}</option></select></label><label>Count<select v-model="count"><option v-for="value in filterOptions.count" :key="value" :value="value">{{ value }}</option></select></label><label>Pitch<select v-model="pitch"><option v-for="value in filterOptions.pitch" :key="value" :value="value">{{ value }}</option></select></label><label>Pitch result<select v-model="pitchResult"><option v-for="value in filterOptions.pitch_result" :key="value" :value="value">{{ displayFilter(value) }}</option></select></label><label>In play result<select v-model="inPlayResult"><option v-for="value in filterOptions.in_play_result" :key="value" :value="value">{{ displayFilter(value) }}</option></select></label><label>PA result<select v-model="paResult"><option v-for="value in filterOptions.pa_result" :key="value" :value="value">{{ displayFilter(value) }}</option></select></label><label>Panel group<select v-model="periodPanelGroup"><option value="All">All</option><option value="result">Result</option><option value="discipline">Discipline</option><option value="situation">Situation</option></select></label>
          <button class="apply-filter" type="button" :disabled="pending" @click="loadComparison">{{ pending ? 'Loading…' : 'Apply filters' }}</button>
        </template>
      </ComparisonPeriodWorkspace>
      <ComparisonNotes :notes="comparison.meta.warnings" />
    </template>
  </main>
</template>

<script setup lang="ts">
import type { BatterOption, BatterPeriodComparisonResponse, BatterPeriodMetric, ComparisonPlayer, ComparisonTeamStint, TablePayload } from '~/types/api'
const activeRoute = useRoute(); if (activeRoute.path === '/comparison/batter-period') await navigateTo('/batters/comparison/period', { redirectCode: 301 })
const api=useApi(),directoryYear=ref(2026),leftYear=ref(2026),rightYear=ref(2026),team=ref('All'),batterId=ref<number|null>(null)
const leftStart=ref('2026-03-01'),leftEnd=ref('2026-05-31'),rightStart=ref('2026-06-01'),rightEnd=ref('2026-07-31')
const batterSide=ref('All'),pitcherHand=ref('All'),pitchFamily=ref('All'),count=ref('All'),pitch=ref('All'),pitchResult=ref('All'),inPlayResult=ref('All'),paResult=ref('All'),periodPanelGroup=ref('All')
const comparison=ref<BatterPeriodComparisonResponse|null>(null),pending=ref(false),errorMessage=ref(''),filterRailOpen=ref(false),teamStints=ref<ComparisonTeamStint[]>([]),leftStintIndex=ref<number|null>(null),rightStintIndex=ref<number|null>(null),applyingTeamStints=ref(false)
const {data:options,refresh:refreshOptions}=await useAsyncData(()=>`batter-period-options-${directoryYear.value}`,()=>api.batterPeriodOptions(directoryYear.value),{default:()=>({meta:{year:directoryYear.value,data_updated_at:null,warnings:[]},years:[directoryYear.value],batters:[]})})
const yearOptions=computed(()=>options.value.years.length?options.value.years:[directoryYear.value]),allBatters=computed<BatterOption[]>(()=>options.value.batters),teamOptions=computed(()=>[...new Set(allBatters.value.map(b=>b.team).filter(Boolean))].sort()),batterOptions=computed(()=>team.value==='All'?allBatters.value:allBatters.value.filter(b=>b.team===team.value)),selectedBatter=computed(()=>allBatters.value.find(b=>b.value===batterId.value)||comparison.value?.batter||null)
const canApply=computed(()=>Boolean(batterId.value&&leftStart.value&&leftEnd.value&&rightStart.value&&rightEnd.value)),filterOptions=computed(()=>comparison.value?.filters||{batter_side:['All','L','R'],pitcher_hand:['All','L','R'],pitch_family:['All','Fastball','Breaking','Offspeed','Other'],count:['All'],pitch:['All'],pitch_result:['All','Swing','Whiff','In Play'],in_play_result:['All'],pa_result:['All','Hit','Out','home_run','Strikeout']})
const higherBetter=new Set(['ops','woba','xwoba','avg','obp','slg','avg_ev','max_ev','barrel_pct','hard_hit_pct','sweet_spot_pct','contact_pct','bb_pct','avg_bat_speed','fast_swing_pct','squared_up_pct','blast_pct']),lowerBetter=new Set(['chase_pct','whiff_pct','k_pct','k_bb_pct','avg_miss_distance'])
const metricComparisonTable=computed<TablePayload>(()=>({columns:[{key:'Metric',label:'Metric'},{key:'Period A',label:'Period A'},{key:'Period B',label:'Period B'},{key:'Delta',label:'Δ B − A'},{key:'Sample',label:'Denominator A / B'}],rows:(comparison.value?.metrics||[]).map(m=>({Metric:m.label,'Period A':formatValue(m.period_a,m.unit),'Period B':formatValue(m.period_b,m.unit),Delta:formatDelta(m.delta,m.delta_unit),Sample:`${m.denominator_label} · ${m.period_a_denominator.toLocaleString()} / ${m.period_b_denominator.toLocaleString()}`}))}))
function advantageRows(side:'left'|'right'){return(comparison.value?.metrics||[]).filter(m=>m.delta!==null&&(higherBetter.has(m.key)||lowerBetter.has(m.key))).filter(m=>{const bWins=(higherBetter.has(m.key)&&Number(m.delta)>0)||(lowerBetter.has(m.key)&&Number(m.delta)<0);return side==='right'?bWins:!bWins&&Number(m.delta)!==0}).sort((a,b)=>Math.abs(Number(b.delta))-Math.abs(Number(a.delta))).slice(0,8).map(m=>({Metric:m.label,Display:formatDelta(Math.abs(Number(m.delta)),m.delta_unit)}))}
const leftAdvantages=computed(()=>advantageRows('left')),rightAdvantages=computed(()=>advantageRows('right'))
function periodPlayer(side:'left'|'right'):ComparisonPlayer|null{if(!selectedBatter.value||!comparison.value)return null;const period=comparison.value.periods[side];return{player_id:selectedBatter.value.value,display_name:selectedBatter.value.name,team:period.team||selectedBatter.value.team,role:'Batter',display_label:selectedBatter.value.label,meta:{year:period.year,period:`${period.start_date} – ${period.end_date}`,pitches:period.pitches}}}
async function loadDateRanges(){if(!batterId.value||applyingTeamStints.value)return;errorMessage.value='';try{const[leftRange,rightRange]=await Promise.all([api.batterPeriodDateRange({year:leftYear.value,batterId:batterId.value}),api.batterPeriodDateRange({year:rightYear.value,batterId:batterId.value})]),history=leftYear.value===directoryYear.value?leftRange:rightYear.value===directoryYear.value?rightRange:await api.batterPeriodDateRange({year:directoryYear.value,batterId:batterId.value});teamStints.value=history.team_stints||[];leftStintIndex.value=teamStints.value[0]?.stint_index??null;rightStintIndex.value=teamStints.value.at(-1)?.stint_index??null;if(leftYear.value===rightYear.value&&leftRange.start_date&&leftRange.end_date){const start=new Date(`${leftRange.start_date}T00:00:00Z`),end=new Date(`${leftRange.end_date}T00:00:00Z`),mid=new Date((start.getTime()+end.getTime())/2),next=new Date(mid.getTime()+86400000);leftStart.value=leftRange.start_date;leftEnd.value=mid.toISOString().slice(0,10);rightStart.value=next.toISOString().slice(0,10);rightEnd.value=leftRange.end_date}else{if(leftRange.start_date)leftStart.value=leftRange.start_date;if(leftRange.end_date)leftEnd.value=leftRange.end_date;if(rightRange.start_date)rightStart.value=rightRange.start_date;if(rightRange.end_date)rightEnd.value=rightRange.end_date}}catch(error){errorMessage.value=error instanceof Error?error.message:'Failed to load batter date range.'}}
async function applyStintComparison(left:ComparisonTeamStint,right:ComparisonTeamStint){applyingTeamStints.value=true;leftYear.value=directoryYear.value;rightYear.value=directoryYear.value;await nextTick();leftStart.value=left.start_date;leftEnd.value=left.end_date;rightStart.value=right.start_date;rightEnd.value=right.end_date;applyingTeamStints.value=false;await loadComparison()}
async function loadComparison(){if(!canApply.value||!batterId.value)return;pending.value=true;errorMessage.value='';try{comparison.value=await api.batterPeriodOverview({batterId:batterId.value,leftYear:leftYear.value,rightYear:rightYear.value,leftStart:leftStart.value,leftEnd:leftEnd.value,rightStart:rightStart.value,rightEnd:rightEnd.value,batterSide:filterParam(batterSide.value),pitcherHand:filterParam(pitcherHand.value),pitchFamily:filterParam(pitchFamily.value),count:filterParam(count.value),pitch:filterParam(pitch.value),pitchResult:filterParam(pitchResult.value),inPlayResult:filterParam(inPlayResult.value),paResult:filterParam(paResult.value)})}catch(error){errorMessage.value=error instanceof Error?error.message:'Failed to load batter period comparison.'}finally{pending.value=false}}
function filterParam(value:string){return value&&value!=='All'?value:undefined}function displayFilter(value:string){return value.replaceAll('_',' ')}
function formatValue(value:number|null,unit:BatterPeriodMetric['unit']){if(value===null||!Number.isFinite(value))return'—';if(unit==='count')return Math.round(value).toLocaleString();if(unit==='pct')return`${value.toFixed(1)}%`;if(unit==='mph')return`${value.toFixed(1)} mph`;if(unit==='ft')return`${value.toFixed(2)} ft`;if(unit==='in')return`${value.toFixed(2)} in`;return value.toFixed(3).replace(/^0/,'')}function formatDelta(value:number|null,unit:BatterPeriodMetric['delta_unit']){if(value===null||!Number.isFinite(value))return'—';const sign=value>0?'+':'';if(unit==='count')return`${sign}${Math.round(value).toLocaleString()}`;if(unit==='pp')return`${sign}${value.toFixed(1)} pp`;if(unit==='mph')return`${sign}${value.toFixed(1)} mph`;if(unit==='ft')return`${sign}${value.toFixed(2)} ft`;if(unit==='in')return`${sign}${value.toFixed(2)} in`;return`${sign}${value.toFixed(3)}`}
watch(directoryYear,async year=>{team.value='All';batterId.value=null;comparison.value=null;teamStints.value=[];leftYear.value=year;rightYear.value=year;await refreshOptions()});watch(batterOptions,batters=>{if(batterId.value&&!batters.some(b=>b.value===batterId.value))batterId.value=null},{immediate:true});watch([batterId,leftYear,rightYear],async()=>{comparison.value=null;if(!batterId.value){teamStints.value=[];return}await loadDateRanges()})
</script>
<style scoped>
.batter-period-page{max-width:1360px;margin:0 auto;padding:104px 20px 56px}.apply-hint{margin:18px 0;color:var(--color-muted-text);text-align:center}
</style>
